import './ui-icons.js';
import {mountCustomerAssistant} from './customer-assistant.js';
import {mountEvents,readEvents,refreshEventPhotos} from './event-editor.js';
import {mountBusinessLogo} from './business-logo.js';
import {sectors,itemExtras,readItemExtras,refreshItemPhotos,requestNames} from './sector-config.js';
function emailNotice(){return `<section class="panel"><p>Login: ${esc(data.email)} · ${data.emailVerified?'E-mail confirmado':'E-mail ainda não confirmado'}</p>${!data.emailVerified?data.emailEnabled?'<button type="button" class="chip" id="resend-verification">Enviar confirmação de e-mail</button>':'<p class="helper">A confirmação por e-mail será disponibilizada em breve. Seu portal está liberado; páginas e produtos dependem de aprovação.</p>':''}<p id="email-status" role="status"></p></section>`;}
function emailLinkForm(){
 logout.hidden=true;document.querySelector('#account').hidden=true;
 root.innerHTML=`<section class="panel"><h1>${resetToken?'Defina uma nova senha':'Confirme seu e-mail'}</h1><form id="email-link">${resetToken?'<label>Nova senha<input type="password" name="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><label>Repita a senha<input type="password" name="confirm" required minlength="10" maxlength="128" autocomplete="new-password"></label>':'<p>Confirme para validar o e-mail da sua conta Helpu Local.</p>'}<p role="alert"></p><button class="primary">${resetToken?'Salvar nova senha':'Confirmar e-mail'}</button></form><p><a href="/local/cliente.html">Voltar ao login</a></p></section>`;
}
document.addEventListener('click',async e=>{
 if(e.target.closest('#forgot-password')){root.innerHTML='<section class="panel"><h1>Recupere seu acesso.</h1><form id="recover-email"><label>E-mail da conta<input name="email" type="email" required maxlength="254" autocomplete="email"></label><p role="alert"></p><button class="primary">Enviar link de recuperação</button></form><p><a href="/local/cliente.html">Voltar ao login</a></p></section>';return;}
 const verify=e.target.closest('#resend-verification'),pause=e.target.closest('#pause-business');if(!verify&&!pause)return;
 const b=verify||pause;b.disabled=true;
 try{if(verify){await api('resend-verification',{});document.querySelector('#email-status').textContent='E-mail enviado. Confira sua caixa de entrada e o spam.';}else{await api('business-pause',{version:data.business.version});await load();}}
 catch(err){document.querySelector('#email-status').textContent=err.message;}finally{b.disabled=false;}
});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!['recover-email','email-link'].includes(f.id))return;e.preventDefault();const b=f.querySelector('button'),status=f.querySelector('[role=alert]');b.disabled=true;
 try{const d=Object.fromEntries(new FormData(f));if(f.id==='recover-email'){const result=await api('forgot-password',d);status.textContent=result.message;}
 else{if(resetToken&&d.password!==d.confirm)throw Error('As senhas precisam ser iguais.');await api(resetToken?'reset-password':'verify-email',{...d,token:resetToken||verifyToken});const wasReset=!!resetToken;resetToken=null;verifyToken=null;login();root.insertAdjacentHTML('afterbegin','<p class="panel" role="status">'+(wasReset?'Senha atualizada. Entre com sua nova senha.':'E-mail confirmado. Entre no portal para continuar.')+'</p>');}}
 catch(err){status.textContent=err.message;}finally{b.disabled=false;}
});
const root=document.querySelector('#customer'),logout=document.querySelector('#logout');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let leadFilter='Todos';
const linkParams=new URLSearchParams(location.hash.slice(1));let resetToken=linkParams.get('redefinir'),verifyToken=linkParams.get('confirmar');
let editingLogo='',editingPhotos=[],data,activation=linkParams.get('ativar');if(activation||resetToken||verifyToken)history.replaceState(null,'',location.pathname);
async function api(action,body){const r=await fetch('/api/local/customer/'+action,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error||'Não foi possível concluir.'),{status:r.status});return d;}
function login(){logout.hidden=true;document.querySelector('#account').hidden=true;root.innerHTML=`<section id="customer-login"><span class="eyebrow">MEU PORTAL</span><h1 class="page-title">${activation?'Seu acesso começa aqui.':'Bem-vindo de volta.'}</h1><p class="muted">${activation?'Defina sua senha para acessar o portal da sua empresa.':'Entre com o e-mail da sua conta Helpu Local.'}</p><form id="access" class="panel">${activation?'':'<label for="email">E-mail de login</label><input id="email" name="email" type="email" autocomplete="username" required maxlength="254">'}<label for="password">${activation?'Crie sua senha':'Senha'}</label><input id="password" name="password" type="password" autocomplete="${activation?'new-password':'current-password'}" required minlength="10" maxlength="128">${activation?'<label for="confirm">Repita a senha</label><input id="confirm" name="confirm" type="password" autocomplete="new-password" required minlength="10" maxlength="128">':''}<p class="error" role="alert"></p><button class="primary">${activation?'Ativar meu acesso':'Entrar'}</button></form><p><a class="text-link" href="/local/cadastro.html">Ainda não tem conta? Crie sua conta</a></p><p><button class="chip" type="button" id="forgot-password">Esqueci minha senha</button></p></section>`;}
function dashboard(){logout.hidden=false;document.querySelector('#account').hidden=true;const b=data.business;if(b.productsOnly){root.innerHTML=emailNotice()+`<section class="panel"><span class="eyebrow">PORTAL DO ANUNCIANTE</span><h1>Olá, ${esc(b.name)}.</h1><p>Gerencie seus produtos novos e usados, acompanhe a aprovação e marque suas vendas.</p><a class="primary" href="/local/anuncios.html">Meus anúncios de produtos</a> <a href="/local/produtos.html">Explorar produtos</a></section><section class="panel"><h2>Segurança</h2><form id="password-form"><label>Senha atual<input name="currentPassword" type="password" required autocomplete="current-password"></label><label>Nova senha<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><p role="alert"></p><button class="primary">Alterar senha e sair</button></form></section>`;return;}editingLogo=b.logoId||'';editingPhotos=[...(b.photos||[])];const field=(name,label,area=false)=>`<label>${label}${area?`<textarea name="${name}" maxlength="${name==='description'||name==='offer'?3000:name==='address'?300:500}">${esc(b[name])}</textarea>`:`<input name="${name}" value="${esc(b[name])}" required maxlength="${name==='name'?150:30}">`}</label>`;root.innerHTML=emailNotice()+`<div class="customer-head"><span class="eyebrow">SEU PORTAL · ${esc(b.state)}</span><h1 class="page-title customer-identity">${b.logo?`<img class="customer-business-logo" src="${esc(b.logo)}" alt="${esc(b.name)}">`:esc(b.name)}</h1><p class="muted">Informações, contatos e próximos passos do seu negócio.</p>${b.state==='Publicado'?`<a class="text-link" href="/local#/negocio?id=${encodeURIComponent(b.id)}" target="_blank" rel="noopener">Ver minha página ↗</a>`:b.state==='Em análise'?'<p>Sua página foi enviada. Aguarde a revisão da Helpu; ela aparecerá após aprovação.</p>':'<p>Sua página está fora da vitrine. Confira os dados e envie para análise. Ela aparecerá após aprovação da Helpu.</p><button class="primary" data-open-editor="information">Preparar publicação ↗</button>'}${b.moderationReason?`<p role="status">Motivo da revisão: ${esc(b.moderationReason)}</p>`:''}${['Publicado','Em análise'].includes(b.state)?'<button class="chip" type="button" id="pause-business">Pausar página</button>':''}</div>${profileReadiness(b)}<div class="metrics"><div class="panel"><strong data-metric="view">${data.metrics.view}</strong><span>Visitas · últimos 30 dias</span></div><div class="panel"><strong data-metric="whatsapp">${data.metrics.whatsapp}</strong><span>Cliques no WhatsApp · 30 dias</span></div><div class="panel"><strong data-metric="newContacts">${data.metrics.newContacts}</strong><span>Contatos novos</span></div></div><p class="helper">Visitas são carregamentos registrados, não pessoas únicas. Cliques não confirmam conversas ou vendas. Indicadores contados a partir da ativação desta funcionalidade.</p><button type="button" class="chip" id="refresh-metrics">Atualizar resultados</button><p class="helper" id="metrics-status" role="status">Atualização automática a cada minuto. Os números começam a contar quando o anúncio está publicado.</p><section class="panel"><h2>Meus anúncios de produtos</h2><p>Venda itens novos e usados no marketplace e acompanhe os anúncios da sua loja.</p><a class="primary" href="/local/anuncios.html">Gerenciar produtos</a> <a href="/local/produtos.html">Ver marketplace</a></section><div class="customer-nav"><a href="#contatos">Contatos recebidos</a><a href="#informacoes">Minhas informações</a><a href="#seguranca">Segurança</a></div><div class="customer-columns"><section class="panel" id="contatos"><h2>Contatos recebidos</h2><p class="helper">Últimos 200 pedidos enviados pelo formulário da sua página. Conversas iniciadas diretamente no WhatsApp são atendidas no seu número.</p><div class="lead-toolbar"><label>Mostrar contatos<select id="lead-filter">${['Todos','Novo','Em atendimento','Confirmado','Concluído','Cancelado'].map(s=>`<option ${leadFilter===s?'selected':''}>${s}</option>`).join('')}</select></label><span id="lead-count" class="helper"></span></div><div id="lead-list">${leadCards(data.leads)}</div></section><section id="informacoes"><form id="profile" class="panel"><h2>Minhas informações</h2>${field('name','Nome do negócio')}<label>Segmento<select name="sector">${sectors.map(s=>`<option ${s===b.sector?'selected':''}>${esc(s)}</option>`).join('')}</select></label>${field('publicPhone','WhatsApp que recebe os contatos')}${field('description','Sobre o negócio',true)}${field('address','Endereço ou região atendida',true)}${field('hours','Horários',true)}${field('offer','Informações adicionais',true)}<h2>Fotos do negócio</h2><div class="business-logo-editor" id="customer-logo"></div><p class="helper">Sugestão: 1600 × 1000 pixels, com o conteúdo principal no centro. Outros tamanhos também são aceitos e se ajustam ao espaço, sem distorcer. A primeira foto é a capa.</p><div id="customer-photos">${photoCards()}</div><label>Adicionar imagens · JPG, PNG ou WebP<input id="customer-photo-input" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p class="helper">Até seis fotos, 25 MB por arquivo. Otimizamos as imagens automaticamente para carregar mais rápido.</p><p id="photo-status" role="status"></p><h2>Meu catálogo</h2><div id="customer-catalog">${(b.catalog||[]).map(itemEditor).join('')}</div><button type="button" class="chip" id="add-item">Adicionar produto ou serviço</button><h2>Eventos do negócio</h2><div id="customer-events"></div><p class="helper">Salvar alterações retira a página da vitrine. Envie novamente para análise; ela volta somente após aprovação. Trocar o WhatsApp altera o destino dos novos contatos; não transfere conversas anteriores.</p><p class="error" role="alert"></p><button type="submit" class="primary">Salvar rascunho</button><p class="helper">Ao aprovar, a Helpu libera nome, fotos, descrição, catálogo e WhatsApp na vitrine.</p><button type="submit" class="primary" name="intent" value="publish">Enviar para análise</button></form></section></div><section id="seguranca"><form id="password-form" class="panel"><h2>Alterar senha</h2><label>Senha atual<input name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"></label><label>Nova senha<input name="password" type="password" autocomplete="new-password" required minlength="10" maxlength="128"></label><p class="error" role="alert"></p><button class="primary">Alterar senha e sair</button></form></section>`;organizeDashboard();mountBilling();updateLeadCount();mountCustomerAssistant(root,{api,getBusiness:()=>data.business,applyDescription:text=>{openEditor('information');const field=document.querySelector('#profile [name=description]');field.value=text;field.focus();document.querySelector('#profile [role=alert]').textContent='Sugestão aplicada ao formulário. Revise e salve para publicar.';}});mountEvents(document.querySelector('#customer-events'),b.events||[],()=>editingPhotos);mountBusinessLogo(document.querySelector('#customer-logo'),{id:editingLogo,url:b.logo,upload:async file=>{const r=await fetch('/api/local/customer/photo',{method:'POST',headers:{'Content-Type':file.type,'X-File-Name':'logo.png'},body:file});const d=await r.json();if(!r.ok)throw Error(d.error||'Falha no envio.');return d;},onChange:id=>editingLogo=id});}
async function load(){try{data=await api('me');dashboard();}catch(e){if(e.status===401||e.status===403)login();else root.innerHTML='<p role="alert">'+esc(e.message)+'</p><a href="/local/cliente.html">Tentar novamente</a>';}}
document.addEventListener('submit',async e=>{const f=e.target;if(!['access','profile','password-form'].includes(f.id))return;e.preventDefault();const b=e.submitter||f.querySelector('button[type=submit]')||f.querySelector('button'),error=f.querySelector('[role=alert]');b.disabled=true;error.textContent='';try{const d=Object.fromEntries(new FormData(f));if(f.id==='access'){if(activation&&d.password!==d.confirm)throw Error('As senhas precisam ser iguais.');await api(activation?'activate':'login',{...d,...activation?{token:activation}:{}});activation=null;await load();}else if(f.id==='profile'){await api('profile',{...d,publish:e.submitter?.value==='publish',version:data.business.version,events:readEvents(f),logoId:editingLogo,photos:editingPhotos.map(p=>p.id),catalog:[...f.querySelectorAll('.customer-item')].map(el=>({...readItemExtras(el,data.business.catalog.find(x=>x.id===el.dataset.id)||{}),id:el.dataset.id,name:el.querySelector('[data-name]').value,description:el.querySelector('[data-description]').value,priceCents:el.querySelector('[data-price]').value===''?null:Math.round(Number(el.querySelector('[data-price]').value)*100),available:el.querySelector('[data-available]').checked}))});await load();root.insertAdjacentHTML('afterbegin','<p class="panel" role="status">'+(e.submitter?.value==='publish'?'Página enviada para análise. Ela ficará pública após aprovação.':'Rascunho salvo. Sua página está fora da vitrine até ser enviada e aprovada.')+'</p>');}else{await api('password',d);await api('logout',{});login();}}catch(e){error.className='error';error.textContent=e.message;}finally{b.disabled=false;}});
document.addEventListener('change',async e=>{if(!e.target.matches('[data-lead]'))return;const el=e.target;el.disabled=true;try{await api('lead',{id:el.dataset.lead,version:Number(el.dataset.version),state:el.value});await refreshMetrics();}catch(err){el.closest('.lead').querySelector('[role=alert]').textContent=err.message;}finally{el.disabled=false;}});
logout.addEventListener('click',async()=>{try{await api('logout',{});login();}catch(e){alert(e.message);}});if(resetToken||verifyToken)emailLinkForm();else if(activation)login();else load();

function itemEditor(x={}){return `<fieldset class="customer-item" data-id="${esc(x.id||crypto.randomUUID())}"><label>Nome<input data-name required maxlength="120" value="${esc(x.name)}"></label><label>Descrição<textarea data-description maxlength="1000">${esc(x.description)}</textarea></label><label>Preço em R$ · vazio para consulta<input data-price type="number" min="0" max="1000000" step="0.01" value="${x.priceCents==null?'':x.priceCents/100}"></label>${itemExtras(x,data.business.sector,esc,editingPhotos)}<label class="consent"><input data-available type="checkbox" ${x.available!==false?'checked':''}> Disponível</label><button type="button" class="chip" data-remove-item>Remover</button></fieldset>`;}
document.addEventListener('click',e=>{if(e.target.id==='add-item'){const el=document.querySelector('#customer-catalog');if(el.children.length<30)el.insertAdjacentHTML('beforeend',itemEditor());}if(e.target.closest('[data-remove-item]'))e.target.closest('.customer-item').remove();});

function photoCards(){return editingPhotos.map((p,i)=>`<div class="customer-photo"><img src="${esc(p.url)}" alt="Foto ${i+1}" loading="lazy"><span>${i===0?'Capa':'Foto '+(i+1)}</span><button type="button" class="chip" data-photo-remove="${esc(p.id)}">Remover</button>${i?`<button type="button" class="chip" data-photo-cover="${esc(p.id)}">Usar como capa</button>`:''}</div>`).join('');}
function drawPhotos(){document.querySelector('#customer-photos').innerHTML=photoCards();refreshItemPhotos(document.querySelector('#profile'),editingPhotos,esc);refreshEventPhotos(document.querySelector('#profile'),editingPhotos);}
document.addEventListener('click',e=>{const rm=e.target.closest('[data-photo-remove]'),cover=e.target.closest('[data-photo-cover]');if(rm){editingPhotos=editingPhotos.filter(p=>p.id!==rm.dataset.photoRemove);drawPhotos();}if(cover){editingPhotos=[editingPhotos.find(p=>p.id===cover.dataset.photoCover),...editingPhotos.filter(p=>p.id!==cover.dataset.photoCover)];drawPhotos();}});
async function optimizePhoto(file){if(file.size>25*1024*1024)throw Error('Use uma imagem de até 25 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Use JPG, PNG ou WebP.');const bitmap=await createImageBitmap(file);try{const scale=Math.min(1,2000/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);for(const quality of [.88,.75,.6,.4]){const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',quality));if(blob&&blob.size<3*1024*1024)return blob;}throw Error('Não foi possível otimizar esta imagem. Tente salvá-la em JPG.');}finally{bitmap.close();}}
document.addEventListener('change',async e=>{if(e.target.id!=='customer-photo-input')return;const input=e.target,files=[...input.files],form=document.querySelector('#profile'),button=form.querySelector('[type=submit]'),status=document.querySelector('#photo-status');if(files.length+editingPhotos.length>6){status.textContent='Use até seis fotos. Remova uma antes de adicionar outra.';input.value='';return;}input.disabled=true;form.querySelectorAll('[type=submit]').forEach(b=>b.disabled=true);try{for(const file of files){status.textContent='Preparando '+file.name+'…';const blob=await optimizePhoto(file),r=await fetch('/api/local/customer/photo',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'image/jpeg','X-File-Name':encodeURIComponent(file.name.replace(/\.[^.]+$/,'').slice(0,140)+'.jpg')},body:blob}),d=await r.json();if(!r.ok)throw Error(d.error||'Não foi possível enviar a foto.');if(!form.isConnected)return;editingPhotos.push(d);drawPhotos();}status.textContent='Fotos prontas. Clique em Salvar rascunho ou Enviar para análise para guardar as fotos.';}catch(err){status.textContent=err.message;}finally{input.disabled=false;form.querySelectorAll('[type=submit]').forEach(b=>b.disabled=false);input.value='';}});

function leadCards(leads){leads=leads.filter(l=>leadFilter==='Todos'||l.state===leadFilter);return leads.length?leads.map(l=>`<article class="lead"><span class="eyebrow">${esc(requestNames[l.request?.type]||'Contato')}</span><div class="lead-heading"><h3>${esc(l.name)}</h3><span class="status-pill">${esc(l.state)}</span></div><p class="helper">${new Date(l.createdAt).toLocaleString('pt-BR')}</p><p class="local-lines">${esc(l.message)}</p><a class="text-link" href="https://wa.me/${encodeURIComponent(l.phone)}" target="_blank" rel="noopener">Responder pelo WhatsApp ↗</a><button type="button" class="chip ai-reply" data-ai-mode="reply" data-ai-lead="${esc(l.id)}">✦ Sugerir resposta</button><label>Andamento<select data-lead="${esc(l.id)}" data-version="${l.version}">${['Novo','Em atendimento','Confirmado','Concluído','Cancelado'].map(s=>`<option ${l.state===s?'selected':''}>${s}</option>`).join('')}</select></label><p class="error" role="alert"></p></article>`).join(''):'<div class="leads-empty"><h3>Nenhum contato neste filtro.</h3><p>Os pedidos recebidos pela sua página aparecerão aqui.</p></div>';}

let refreshing=false;
async function refreshMetrics(){if(refreshing||!document.querySelector('#refresh-metrics'))return;refreshing=true;const status=document.querySelector('#metrics-status');try{const fresh=await api('me');data.leads=fresh.leads;for(const [key,value]of Object.entries(fresh.metrics)){const el=document.querySelector('[data-metric="'+key+'"]');if(el)el.textContent=value;}document.querySelector('#lead-list').innerHTML=leadCards(fresh.leads);updateLeadCount();status.textContent='Atualizado às '+new Date().toLocaleTimeString('pt-BR')+' · Atualização automática a cada minuto.';}catch(err){status.textContent=err.message;}finally{refreshing=false;}}
document.addEventListener('click',e=>{if(e.target.closest('#refresh-metrics'))refreshMetrics();});setInterval(()=>{if(!document.hidden&&!document.activeElement?.closest('#contatos'))refreshMetrics();},60000);

function organizeDashboard(){
 document.querySelector('#account').hidden=false;
 document.querySelector('.customer-nav')?.remove();
 const form=document.querySelector('#profile'),info=document.querySelector('#informacoes'),security=document.querySelector('#seguranca');
 const headings=[...form.querySelectorAll(':scope > h2')],parts=[];
 for(let i=0;i<4;i++){const section=document.createElement('details');section.className='editor-section';section.dataset.editorSection=['information','photos','catalog','events'][i];const summary=document.createElement('summary');summary.textContent=['Informações do negócio','Fotos e capa','Produtos e serviços','Eventos e programação'][i];section.append(summary);const content=document.createElement('div');content.className='editor-fields';let node=headings[i].nextSibling;while(node&&node!==headings[i+1]){if(i===3&&node.nodeType===1&&node.classList.contains('helper'))break;const next=node.nextSibling;content.append(node);node=next;}section.append(content);parts.push(section);headings[i].remove();}
 form.prepend(...parts);parts[0].open=true;
 const actions=document.createElement('div');actions.className='editor-actions';let node=parts[3].nextSibling;while(node){const next=node.nextSibling;actions.append(node);node=next;}form.append(actions);
 const dialog=document.createElement('dialog');dialog.id='business-editor';dialog.className='customer-dialog';dialog.setAttribute('aria-labelledby','business-editor-title');dialog.innerHTML='<div class="dialog-heading"><div><span class="eyebrow">SEU ANÚNCIO</span><h2 id="business-editor-title">Editar meu negócio</h2></div><button type="button" class="chip" data-close-dialog aria-label="Fechar edição">Fechar ×</button></div>';dialog.append(form);root.append(dialog);
 info.innerHTML=`<div class="panel business-overview"><span class="eyebrow">SEU ANÚNCIO</span><h2>Sua presença na cidade.</h2>${data.business.photos?.[0]?`<img class="overview-cover" src="${esc(data.business.photos[0].url)}" alt="Capa de ${esc(data.business.name)}">`:''}<p class="muted">Atualize sua página por assunto, quando precisar.</p><button class="overview-action" data-open-editor="information"><span><strong>Informações do negócio</strong><small>Nome, descrição, WhatsApp e horários</small></span><span data-icon="arrow"></span></button><button class="overview-action" data-open-editor="photos"><span><strong>Fotos e capa</strong><small>${data.business.photos?.length||0} de 6 fotos · escolha a imagem principal</small></span><span data-icon="arrow"></span></button><button class="overview-action" data-open-editor="catalog"><span><strong>Produtos e serviços</strong><small>${data.business.catalog?.length||0} itens no catálogo</small></span><span data-icon="arrow"></span></button><button class="overview-action" data-open-editor="events"><span><strong>Eventos e programação</strong><small>Datas, horários, ingressos e condições</small></span><span data-icon="arrow"></span></button>${data.business.state!=='Publicado'?'<button class="primary" data-open-editor="information">Preparar publicação</button>':''}</div>`;
 const account=document.createElement('dialog');account.id='account-dialog';account.className='customer-dialog account-dialog';account.setAttribute('aria-labelledby','account-title');account.innerHTML='<div class="dialog-heading"><div><span class="eyebrow">MINHA CONTA</span><h2 id="account-title">Acesso e segurança</h2></div><button type="button" class="chip" data-close-dialog aria-label="Fechar minha conta">Fechar ×</button></div><p class="helper">Login: '+esc(data.email)+'</p>';account.append(security.querySelector('form'));security.remove();root.append(account);
 const refresh=document.querySelector('#refresh-metrics'),status=document.querySelector('#metrics-status'),toolbar=document.createElement('div');toolbar.className='results-toolbar';refresh.before(toolbar);toolbar.append(status,refresh);
 const explanation=document.querySelector('.metrics').nextElementSibling;if(explanation?.classList.contains('helper')){const details=document.createElement('details');details.className='metrics-help';details.innerHTML='<summary>Como os indicadores são contados</summary>';explanation.before(details);details.append(explanation);}
}
function openEditor(section){const dialog=document.querySelector('#business-editor');dialog.querySelectorAll('.editor-section').forEach(d=>d.open=d.dataset.editorSection===section);dialog.showModal();dialog.scrollTop=0;}
document.addEventListener('click',e=>{const open=e.target.closest('[data-open-editor]');if(open)openEditor(open.dataset.openEditor);if(e.target.closest('#account'))document.querySelector('#account-dialog')?.showModal();const close=e.target.closest('[data-close-dialog]');if(close)close.closest('dialog').close();});
document.addEventListener('invalid',e=>{const details=e.target.closest('.editor-section');if(details)details.open=true;},true);

function profileReadiness(b){const checks=[['Logo',!!b.logo,'photos'],['Fotos',!!b.photos?.length,'photos'],['Descrição',b.description?.length>=20,'information'],['Região',!!b.address,'information'],['Horários',!!b.hours,'information'],['WhatsApp',!!b.publicPhone,'information']],done=checks.filter(x=>x[1]).length,percent=Math.round(done/checks.length*100);return `<section class="profile-readiness" id="profile-readiness"><div><span class="eyebrow">SUA VITRINE</span><h2>${percent===100?'Seu negócio, pronto para ser descoberto.':'Uma página completa inspira confiança.'}</h2><p>${done} de ${checks.length} informações essenciais preenchidas.</p><progress class="readiness-track" aria-label="Informações essenciais preenchidas" max="${checks.length}" value="${done}">${percent}%</progress><div class="readiness-items">${checks.map(([label,ok,target])=>`<button type="button" data-open-editor="${target}" class="${ok?'complete':''}">${ok?'✓':'+'} ${label}</button>`).join('')}</div></div><div class="assistant-entry"><span class="assistant-orb" aria-hidden="true">✦</span><h3>Uma ajuda para o próximo passo.</h3><p>Melhore sua apresentação e prepare respostas com o contexto do seu negócio.</p><button type="button" class="chip" data-ai-mode="profile">Melhorar descrição com IA ↗</button></div></section>`;}
function refreshIdentity(){const b=data.business,el=document.querySelector('.customer-identity');if(el)el.innerHTML=b.logo?`<img class="customer-business-logo" src="${esc(b.logo)}" alt="${esc(b.name)}">`:esc(b.name);const panel=document.querySelector('#profile-readiness');if(panel)panel.outerHTML=profileReadiness(b);}
function updateLeadCount(){const el=document.querySelector('#lead-count');if(el)el.textContent=(data?.leads||[]).filter(l=>leadFilter==='Todos'||l.state===leadFilter).length+' contatos';}
document.addEventListener('change',e=>{if(e.target.id==='lead-filter'){leadFilter=e.target.value;document.querySelector('#lead-list').innerHTML=leadCards(data.leads);updateLeadCount();}});

function mountBilling(){const b=data.billing;if(!b)return;const date=b.freeUntil?new Date(b.freeUntil).toLocaleDateString('pt-BR'):null;const section=document.createElement('section');section.id='faturamento';section.className='panel billing-panel';section.innerHTML=`<div><span class="eyebrow">PLANO E FATURAMENTO</span><h2>Helpu Local</h2><p class="billing-price">R$ 89,90 <small>/ mês</small></p><span class="status-pill">${b.status==='prelaunch'?'Sem cobrança ativa':b.status==='free_period'?'Mês gratuito':'Aguardando ativação da assinatura'}</span></div><div><h3>${b.status==='prelaunch'?'Seu plano ainda não foi ativado.':b.status==='free_period'?'Aproveite seu período gratuito.':'Seu plano está preparado.'}</h3><p>${b.status==='prelaunch'?'O catálogo já está aberto. A publicação depende da aprovação da equipe. O período gratuito e a assinatura serão confirmados antes de qualquer cobrança.':b.status==='free_period'?'Sua isenção está válida até '+esc(date)+'. Depois, o plano será de R$ 89,90 por mês.':'O plano mensal será ativado após a contratação. Nenhuma cobrança automática está ativa.'}</p><p class="helper">Marketing Helpu é um serviço independente.</p><details><summary>Assinatura, pagamentos e faturas</summary><dl><dt>Forma de pagamento</dt><dd>Não cadastrada</dd><dt>Próxima cobrança</dt><dd>${b.status==='prelaunch'?'A definir na contratação':date?'Após '+esc(date)+', mediante ativação':'A definir na contratação'}</dd><dt>Faturas</dt><dd>Nenhuma fatura emitida</dd></dl><p class="helper">O pagamento via Stripe será disponibilizado em breve. Você receberá as orientações para ativar a assinatura; nenhum pagamento é solicitado agora.</p></details></div>`;document.querySelector('#informacoes').after(section);const link=document.createElement('a');link.className='chip';link.href='#faturamento';link.textContent='Plano e faturamento';document.querySelector('.customer-head').append(link);}
